<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Faturamento de tarefas avulsas';require APPPATH.'views/admin/companies/layout_head.php';$esc=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=CompanyRequestScope::adminUrl($this,'company_standalone_billing');$hidden=function($action)use($esc,$company_standalone_billing_csrf,$request_key,$task,$billing){foreach(['action'=>$action,'company_standalone_billing_csrf'=>$company_standalone_billing_csrf,'request_key'=>$request_key,'task_id'=>$task['id'],'revision'=>$task['revision']] as $k=>$v)echo '<input type="hidden" name="'.$esc($k).'" value="'.$esc($v).'">';if($billing)echo '<input type="hidden" name="origin_id" value="'.(int)$billing['origin_id'].'">';}; ?>
<section class="company-settings-card"><h1>Faturamento de tarefas avulsas</h1><p>Uma tarefa concluída, seus timers encerrados e um cliente ativo próprio escolhido explicitamente. A emissão cria uma conta a receber; nenhum recebimento é registrado.</p><?php if($error){ ?><p role="alert"><?= $esc($error); ?></p><?php } ?>
<?php if(!$task){ ?><ul><?php foreach(($tasks['items']??[]) as $t){ ?><li><a href="<?= $esc($url.'?task='.(int)$t['id']); ?>"><?= $esc($t['name'].' · '.$t['status']); ?></a></li><?php } ?></ul><?php if($tasks['next']??null){ ?><a href="<?= $esc($url.'?after='.(int)$tasks['next']); ?>">Próxima página</a><?php }}else{ ?><h2><?= $esc($task['name']); ?></h2><a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_standalone_tasks?task='.(int)$task['id'])); ?>">Voltar à tarefa avulsa</a><p>Revisão <?= (int)$task['revision']; ?></p><h3>Timers da revisão</h3><ul><?php foreach(($billing?$billing['source']['timers']:$task['timers']) as $timer){ ?><li>Funcionário #<?= (int)$timer['actor_id']; ?> · <?= $esc($timer['started_at']); ?> · <?= $timer['stopped_at']===null?'Em execução':$esc($timer['seconds'].' segundos, encerrado em '.$timer['stopped_at']); ?></li><?php } ?></ul>
<?php if($billing){$payload=$billing['payload'];$profile=$billing['source']['billing_profile'];$totals=CompanyInvoiceAmounts::calculate($payload['items'],array_intersect_key($payload,array_flip(['discount_mode','discount_value','discount_type','adjustment']))); ?><h3>Declaração preservada #<?= (int)$billing['origin_id']; ?></h3><dl><dt>Estado do vínculo (histórico)</dt><dd id="standalone-billing-state"><?= $esc(['ready'=>'Preparada','converting'=>'Emissão reservada','converted'=>'Faturada','disabled'=>'Retirada'][$billing['state']]??$billing['state']); ?></dd><dt>Cliente na origem</dt><dd id="standalone-billing-recipient"><?= $esc($billing['recipient']['name']); ?></dd><dt>Horas e taxa</dt><dd><?= $esc($profile['hours'].' × '.$profile['rate']); ?></dd><dt>Valor original da declaração</dt><dd id="standalone-billing-total"><?= $esc($billing['currency'].' · '.$totals['total']); ?></dd><dt>Subtotal / tributos / desconto / ajuste</dt><dd><?= $esc($totals['subtotal'].' / '.$totals['tax'].' / '.$totals['discount_total'].' / '.$totals['adjustment']); ?></dd></dl><table class="table"><thead><tr><th>Origem do item</th><th>Quantidade</th><th>Taxa</th><th>Tributos</th></tr></thead><tbody><?php foreach($payload['items'] as $item){ ?><tr><td><?= $esc($item['description']); ?></td><td><?= $esc($item['qty']); ?></td><td><?= $esc($item['rate']); ?></td><td><?php foreach($item['taxes'] as $tax){ ?><?= $esc($tax['name'].' '.$tax['rate'].'%'); ?><br><?php } ?></td></tr><?php } ?></tbody></table><?php if(isset($profile['excluded_zero_quantity_timer_ids'])&&$profile['excluded_zero_quantity_timer_ids']){ ?><p>Timers preservados, arredondados para 0.00 h e sem item: <?= $esc(implode(', ',$profile['excluded_zero_quantity_timer_ids'])); ?>.</p><?php } ?><?php if($billing['stale']){ ?><p role="status">A origem mudou; revise a declaração pendente antes de emitir.</p><?php } ?><?php require APPPATH.'views/admin/companies/billing_invoice_current.php'; ?><?php if($billing['invoice_id']){ ?><a id="standalone-billing-invoice" href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_invoices?invoice='.(int)$billing['invoice_id'])); ?>">Abrir fatura vinculada</a><?php }elseif(in_array($billing['state'],['ready','converting'],true)){ ?><?= form_open($url,['id'=>'standalone-billing-convert']);$hidden('convert'); ?><button id="standalone-billing-issue" type="submit"><?= $billing['state']==='converting'?'Retomar a mesma emissão':'Emitir fatura da declaração revisada'; ?></button><?= form_close(); ?><?php }if($billing['state']==='ready'||$billing['can_release']){ ?><?= form_open($url,['id'=>'standalone-billing-disable']);$hidden('disable'); ?><button type="submit">Retirar declaração sem apagar histórico</button><?= form_close(); ?><?php }}
if(in_array($task['billing_state']??'none',['partially_billed','converting'],true)){ ?><p>Esta tarefa possui horas selecionadas ou uma reserva em lote. <a href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_time_batches?kind=standalone')); ?>">Revisar lotes e timers restantes</a></p><?php }if(!in_array($task['billing_state']??'none',['partially_billed','converting'],true)&&$task['status']==='done'&&(!$billing||in_array($billing['state'],['ready','disabled'],true))){ ?><h3>Escolher cliente e revisar valores</h3><form method="get" action="<?= $esc($url); ?>"><input type="hidden" name="task" value="<?= (int)$task['id']; ?>"><label>Buscar cliente próprio<input name="q" value="<?= $esc($search); ?>" maxlength="120"></label><button type="submit">Buscar</button></form><?php if($customers['next']!==null){ ?><a href="<?= $esc($url.'?'.http_build_query(['task'=>(int)$task['id'],'q'=>$search,'customer_after'=>$customers['next']])); ?>">Próxima página de clientes próprios</a><?php } ?><?= form_open($url,['id'=>'standalone-billing-prepare']);$hidden('prepare'); ?><label>Cliente próprio<select id="standalone-billing-client" name="billing[client_id]" required><option value="">Selecione explicitamente</option><?php foreach($customers['items'] as $c){ ?><option value="<?= (int)$c['userid']; ?>"><?= $esc($c['company']); ?></option><?php } ?></select></label><label>Moeda<select id="standalone-billing-currency" name="billing[currency]"><?php foreach($currencies as $c){ ?><option value="<?= (int)$c['id']; ?>"><?= $esc($c['name']); ?></option><?php } ?></select></label><label>Data<input id="standalone-billing-date" type="date" name="billing[date]" value="<?= gmdate('Y-m-d'); ?>" required></label><label>Vencimento<input id="standalone-billing-due" type="date" name="billing[due_date]" value="<?= gmdate('Y-m-d'); ?>" required></label><label>Taxa por hora<input id="standalone-billing-rate" name="billing[rate]" inputmode="decimal" required></label><label>Formato<select id="standalone-billing-lines" name="billing[line_mode]"><option value="task_per_item">Um item para a tarefa</option><option value="timesheets_individually">Uma linha por timer encerrado</option></select></label><label>Arredondamento<select id="standalone-billing-round" name="billing[round_mode]"><option value="none">Sem intervalo</option><option value="up">Para cima</option><option value="down">Para baixo</option><option value="nearest">Mais próximo, empate para cima</option></select></label><label>Intervalo em minutos<select id="standalone-billing-minutes" name="billing[round_minutes]"><?php foreach([0,5,10,15,20,25,30,35,40,45] as $m){ ?><option value="<?= $m; ?>"><?= $m; ?></option><?php } ?></select></label><p>Sem intervalo exige 0; demais modos exigem 5 a 45 minutos. Horas têm duas casas. Linhas por timer arredondam cada duração separadamente.</p><fieldset><legend>Tributos (até 10)</legend><?php for($i=0;$i<10;$i++){ ?><label>Nome<input name="billing[taxes][<?= $i; ?>][name]" maxlength="100"></label><label>Alíquota%<input name="billing[taxes][<?= $i; ?>][rate]" value="0.00" inputmode="decimal"></label><?php } ?></fieldset><label>Desconto<select name="billing[discount_mode]"><option value="fixed">Valor fixo</option><option value="percent">Percentual</option></select></label><label>Valor<input name="billing[discount_value]" value="0.00" inputmode="decimal"></label><label>Aplicação<select name="billing[discount_type]"><option value="after_tax">Após tributos</option><option value="before_tax">Antes dos tributos</option></select></label><label>Ajuste com sinal<input name="billing[adjustment]" value="0.00" inputmode="decimal"></label><label>Nota<textarea name="billing[note]" maxlength="20000"></textarea></label><label><input id="standalone-billing-confirm" type="checkbox" name="billable" value="1" required> Conferi cliente próprio, timers, moeda, tributos e valores.</label><button id="standalone-billing-review" type="submit">Preservar declaração para revisão</button><?= form_close(); ?><?php }elseif($task['status']!=='done'){ ?><p>Conclua a tarefa e pare seus cronômetros antes de declarar o faturamento.</p><?php }} ?></section><?php require APPPATH.'views/admin/companies/layout_tail.php'; ?>
